#include <iostream>
#include <cstdlib>
#include <string>
#include <cstring>
#include <cstdio>
#include <algorithm>
#include <climits>
#include <cmath>
#include <cctype>
#include <stack>
#include <queue>
#include <list>
#include <vector>
#include <set>
#include <map>
#include <sstream>
using namespace std;

typedef long long LL;
const int INF = 0x3f3f3f3f;
const int MAXN = 210;
const int MAXE = MAXN * MAXN;

struct Edge {
    int to, w, next;
} edge[MAXE];

const int dir[4][2] = {{0,1},{0,-1},{1,0},{-1,0}};

int n, T, src = MAXN - 1, sink = src - 1;
int sci[15][15], cap[15][15], maze[65][15][15];
int head[MAXN], cnt;
bool vis[15][15], dp[65][15][15][15][15];

void addEdge(int u, int v, int w) {
    edge[cnt].to = v;
    edge[cnt].w = w;
    edge[cnt].next = head[u];
    head[u] = cnt++;
    edge[cnt].to = u;
    edge[cnt].w = 0;
    edge[cnt].next = head[v];
    head[v] = cnt++;
}

int level[MAXN], cur[MAXN];

bool bfs(int s, int t) {
    memset(level, 0, sizeof(level));
    queue<int> q;
    q.push(s);
    cur[s] = head[s];
    level[s] = 1;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int i = head[u]; i != -1; i = edge[i].next) {
            int v = edge[i].to;
            int w = edge[i].w;
            if (level[v] || !w) continue;
            level[v] = level[u] + 1;
            cur[v] = head[v];
            q.push(v);
            if (v == t) return true;
        }
    }
    return false;
}

int dfs(int x, int t, int flow) {
    if (x == t) return flow;
    int rest = flow;
    for (int &i = cur[x]; i != -1 && rest; i = edge[i].next) {
        int v = edge[i].to;
        int w = edge[i].w;
        if (w && level[v] == level[x] + 1) {
            int k = dfs(v, t, min(rest, w));
            if (!k) level[v] = 0;
            edge[i].w -= k;
            edge[i ^ 1].w += k;
            rest -= k;
        }
    }
    return flow - rest;
}

int dinic(int s, int t) {
    int ans = 0, flow;
    while (bfs(s, t))
        while (flow = dfs(s, t, INF))
            ans += flow;
    return ans;
}

int getId(int x, int y, int k) {
    return (x - 1) * n + y + k * n * n;
}

void explore(int sx, int sy, int cx, int cy, int step) {
    vis[cx][cy] = true;
    dp[step][sx][sy][cx][cy] = true;
    if (step >= T || maze[step][cx][cy]) return;
    for (int d = 0; d < 4; ++d) {
        int nx = cx + dir[d][0];
        int ny = cy + dir[d][1];
        if (nx < 1 || ny < 1 || nx > n || ny > n) continue;
        if (vis[nx][ny] || maze[step][nx][ny]) continue;
        explore(sx, sy, nx, ny, step + 1);
    }
}

void init() {
    memset(cur, 0, sizeof(cur));
    memset(head, -1, sizeof(head));
    cnt = 0;
    // propagate Z using a different method: for each time, mark all cells that become Z
    for (int time = 1; time <= T; ++time) {
        for (int x = 1; x <= n; ++x) {
            for (int y = 1; y <= n; ++y) {
                if (maze[time - 1][x][y])
                    maze[time][x][y] = maze[time - 1][x][y];
                else {
                    for (int d = 0; d < 4; ++d) {
                        int xx = x + dir[d][0];
                        int yy = y + dir[d][1];
                        if (xx < 1 || yy < 1 || xx > n || yy > n) continue;
                        if (maze[time - 1][xx][yy] == 2)
                            maze[time][x][y] = 2;
                    }
                }
            }
        }
    }
    // compute reachable cells using iterative DP over time (like Floyd)
    for (int sx = 1; sx <= n; ++sx) {
        for (int sy = 1; sy <= n; ++sy) {
            if (!sci[sx][sy]) continue;
            memset(vis, 0, sizeof(vis));
            explore(sx, sy, sx, sy, 0);
        }
    }
    // propagate dp across time using a different loop order
    for (int i = 1; i <= T; ++i)
        for (int sx = 1; sx <= n; ++sx)
            for (int sy = 1; sy <= n; ++sy)
                for (int tx = 1; tx <= n; ++tx)
                    for (int ty = 1; ty <= n; ++ty)
                        dp[i][sx][sy][tx][ty] |= dp[i - 1][sx][sy][tx][ty];
}

int main() {
    scanf("%d%d", &n, &T);
    for (int i = 1; i <= n; ++i) {
        char s[15];
        scanf("%s", s + 1);
        for (int j = 1; j <= n; ++j) {
            if (isdigit(s[j]))
                sci[i][j] = s[j] - '0';
            else if (s[j] == 'Y')
                maze[0][i][j] = 1;
            else if (s[j] == 'Z')
                maze[0][i][j] = 2;
        }
    }
    for (int i = 1; i <= n; ++i) {
        char s[15];
        scanf("%s", s + 1);
        for (int j = 1; j <= n; ++j) {
            if (isdigit(s[j]))
                cap[i][j] = s[j] - '0';
        }
    }
    init();
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (sci[i][j])
                addEdge(src, getId(i, j, 0), sci[i][j]);
            if (cap[i][j])
                addEdge(getId(i, j, 1), sink, cap[i][j]);
        }
    }
    for (int x = 1; x <= n; ++x)
        for (int y = 1; y <= n; ++y)
            for (int xx = 1; xx <= n; ++xx)
                for (int yy = 1; yy <= n; ++yy)
                    if (sci[x][y] && cap[xx][yy] && dp[T][x][y][xx][yy])
                        addEdge(getId(x, y, 0), getId(xx, yy, 1), INF);
    printf("%d\n", dinic(src, sink));
    return 0;
}
